css:
.button {
  padding: 15px 30px;
  font-size: 18px;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 500;
  color: #ffffff;
  background-color: #4a4a4a;
  border: none;
  border-radius: 50px;
  box-shadow: 0 8px 15px rgba(0, 0, 0, 0.1);
  transition: all 0.3s ease 0s;
  cursor: pointer;
  outline: none;
  position: relative;
  overflow: hidden;
}

.button::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: linear-gradient(
      45deg,
      #ffffff 25%,
      transparent 25%,
      transparent 75%,
      #ffffff 75%,
      #ffffff
    ),
    linear-gradient(
      45deg,
      #ffffff 25%,
      transparent 25%,
      transparent 75%,
      #ffffff 75%,
      #ffffff
    );
  background-size: 10px 10px;
  background-position:
    0 0,
    5px 5px;
  opacity: 0.1;
  transition: opacity 0.3s ease;
}

.button:before {
  content: "";
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: rgba(255, 255, 255, 0.2);
  transform: rotate(45deg);
  transition: all 0.5s ease;
  opacity: 0;
}

.button:hover {
  background-color: #2ee59d;
  box-shadow: 0 15px 20px rgba(46, 229, 157, 0.4);
  color: #fff;
  transform: translateY(-7px);
}

.button:hover::after {
  opacity: 0.2;
}

.button:hover:before {
  opacity: 1;
  top: -75%;
  left: -75%;
}

.button:active {
  transform: translateY(-3px);
}
